import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-ornamental-divider';

  /* ── Load GLB synchronously from cache ─────────────────────── */
  const gltf = ctx.glbLoader(config.assets.meshUrl);
  const meshRoot = gltf.scene.clone(true);

  /* ── Clone materials & enforce machined-metal PBR ──────────── */
  const clonedMaterials = [];
  const clonedGeometries = [];

  meshRoot.traverse((child) => {
    if (!child.isMesh) return;

    child.castShadow = true;
    child.receiveShadow = true;

    if (child.geometry) {
      clonedGeometries.push(child.geometry);
    }

    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      const newMats = mats.map((src) => {
        const mat = src.clone();
        clonedMaterials.push(mat);

        if ('metalness' in mat) {
          mat.metalness = Math.min(mat.metalness ?? 0.5, 0.55);
        }
        if ('roughness' in mat) {
          mat.roughness = Math.max(mat.roughness ?? 0.5, 0.5);
        }
        if ('clearcoat' in mat) {
          mat.clearcoat = Math.min(mat.clearcoat ?? 0, 0.25);
        }
        if (mat.emissive) {
          mat.emissive.setRGB(0, 0, 0);
        }
        if ('emissiveIntensity' in mat) {
          mat.emissiveIntensity = 0;
        }
        return mat;
      });

      child.material = Array.isArray(child.material) ? newMats : newMats[0];
    }
  });

  group.add(meshRoot);

  /* ── Scene placement ──────────────────────────────────────── */
  const placement = config.scenePlacement ?? {};
  const [px, py, pz] = placement.position ?? [-2.5, 0.7, 0];
  const [rx, ry, rz] = placement.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = placement.scale ?? [1, 1, 1];

  group.position.set(px, py, pz);
  group.rotation.set(rx, ry, rz);
  group.scale.set(sx, sy, sz);

  const baseY = py;
  const activeTweens = [];
  const accent = new THREE.Color(0xff2a38);

  function track(tw) {
    activeTweens.push(tw);
    return tw;
  }

  /* ── Hover: rise-in (subtle, 0.15 scene units) ─────────────── */
  function onPointerEnter() {
    gsap.killTweensOf(group.position);
    track(gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    }));
  }

  function onPointerLeave() {
    gsap.killTweensOf(group.position);
    track(gsap.to(group.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power3.out',
    }));
  }

  /* ── Press-down on click ───────────────────────────────────── */
  function onPointerDown() {
    gsap.killTweensOf(group.scale);
    track(gsap.to(group.scale, {
      x: sx * 0.97, y: sy * 0.97, z: sz * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }));
  }

  function onPointerUp() {
    gsap.killTweensOf(group.scale);
    track(gsap.to(group.scale, {
      x: sx, y: sy, z: sz,
      duration: 0.9,
      ease: 'power4.out',
    }));
  }

  /* ── Click: emit hub-home.select ───────────────────────────── */
  function onClick() {
    if (ctx.emit) {
      ctx.emit('hub-home.select', { source: 'home-ornamental-divider' });
    }
  }

  /* ── Focus: accent edge (emissive signal-red glow) ─────────── */
  function onFocus() {
    clonedMaterials.forEach((mat) => {
      if (mat.emissive) {
        gsap.killTweensOf(mat.emissive);
        track(gsap.to(mat.emissive, {
          r: accent.r, g: accent.g, b: accent.b,
          duration: 0.3, ease: 'power2.out',
        }));
      }
      if ('emissiveIntensity' in mat) {
        gsap.killTweensOf(mat);
        track(gsap.to(mat, {
          emissiveIntensity: 0.45,
          duration: 0.3, ease: 'power2.out',
        }));
      }
    });
  }

  function onBlur() {
    clonedMaterials.forEach((mat) => {
      if (mat.emissive) {
        gsap.killTweensOf(mat.emissive);
        track(gsap.to(mat.emissive, {
          r: 0, g: 0, b: 0,
          duration: 0.4, ease: 'power2.out',
        }));
      }
      if ('emissiveIntensity' in mat) {
        gsap.killTweensOf(mat);
        track(gsap.to(mat, {
          emissiveIntensity: 0,
          duration: 0.4, ease: 'power2.out',
        }));
      }
    });
  }

  /* ── Handlers & metadata ───────────────────────────────────── */
  group.userData.handlers = {
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onPointerUp,
    onClick,
    onFocus,
    onBlur,
  };

  group.userData.nodeId = 'home-ornamental-divider';
  group.userData.parentNode = 'hub-home';
  group.userData.siblings = ['home-headline', 'home-subhead', 'home-hero'];
  group.userData.atlasRegion = { atlas: 0, rect: [0, 0, 512, 320] };
  group.userData.dataBindings = [
    { source: 'trpc.visits.book.slot', target: 'confirmPanel' },
  ];

  /* ── Cleanup ───────────────────────────────────────────────── */
  group.userData.cleanup = function cleanup() {
    activeTweens.forEach((tw) => tw.kill());
    activeTweens.length = 0;

    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    clonedMaterials.forEach((mat) => {
      gsap.killTweensOf(mat);
      if (mat.emissive) gsap.killTweensOf(mat.emissive);
      mat.dispose();
    });

    clonedGeometries.forEach((geo) => geo.dispose());

    group.remove(meshRoot);
  };

  return group;
}
